// Multiple top-level classes for a runnable demo; each would be its own file.
package com.bank.strimmut;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class StringImmutabilityDemo {
    private static final Logger log = Logger.getLogger("BankLog");

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return "[" + r.getLevel() + "] " + r.getMessage() + System.lineSeparator();
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // STRING POOL: two literals are the SAME object (safe only because immutable).
        String a = "SAV2001";
        String b = "SAV2001";
        log.info(() -> "pool: a == b (same object)? " + (a == b));

        // IMMUTABILITY: concat returns a NEW string; original 'a' is unchanged.
        String ignored = a.concat("-COPY");
        log.info(() -> "after concat, a is still: " + a + " (new string was " + ignored + ")");

        // HASHCODE CACHING + stable map key: account numbers key the ledger.
        LedgerService ledger = new LedgerService();
        ledger.register(new Account("SAV2001", "Rajesh", new BigDecimal("1000000")));
        ledger.register(new Account("CUR3001", "Priya",  new BigDecimal("250000")));
        log.info(() -> "lookup SAV2001 balance = Rs." + ledger.balanceOf("SAV2001"));

        // SECURITY: validate-then-use is safe because the string can't change.
        String dest = "CUR3001";
        if (ledger.isValidAccount(dest)) {
            log.info(() -> "validated " + dest + "; using the SAME immutable string to transfer");
            ledger.credit(dest, new BigDecimal("50000"));
        }
        log.info(() -> "CUR3001 after credit = Rs." + ledger.balanceOf("CUR3001"));

        // SECURITY ALTERNATIVE: a PIN uses char[] so it can be wiped from memory.
        char[] pin = {'1', '2', '3', '4'};
        java.util.Arrays.fill(pin, '*'); // cannot do this with a String
        log.fine(() -> "PIN char[] wiped after use");
    }
}

