class Account {
    private final String accountId;   // immutable key
    private final String holderName;
    private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId = id; holderName = name; balance = bal; }
    void debit(BigDecimal a)  { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
    BigDecimal getBalance() { return balance; }
    String getAccountId() { return accountId; }
}

// ─── Would be in LedgerService.java (String keys rely on stable hashCode) ───
class LedgerService {
    private static final Logger log = Logger.getLogger("BankLog");
    private final java.util.Map<String, Account> accounts = new java.util.HashMap<>();
    void register(Account a) { accounts.put(a.getAccountId(), a); }
    boolean isValidAccount(String id) { return accounts.containsKey(id); }
    BigDecimal balanceOf(String id) { return accounts.get(id).getBalance(); }
    void credit(String id, BigDecimal amount) { accounts.get(id).credit(amount); }
}
